import csv
import re
import io

data = """"Khor Virap Zindanı (Ölüm Çukuru)","Ararat","Ermenistan","Ermeni Aydınlatıcı Grigor'un 13 yıl boyunca yılanlar ve akreplerle dolu zifiri karanlık bir kuyuya hapsedildiği bu tarihi manastır. Işığın ve umudun girmediği o klostrofobik çukurun başında durduğunuzda, yıllarca süren o yalnızlığın, deliliğin ve fiziksel acının devasa, ezici frekansı boğazınızı sıkar.",5"Karmir Blur (Kızıl Tepe)","Erivan","Ermenistan","Kadim Urartu şehri Teishebaini'nin vahşi bir kuşatmayla yakılıp yıkıldığı, ok yağmurları ve alevler içinde yok olan bu kanlı höyük. Toprak altından çıkarılan binlerce iskeletin yarattığı o ani ölüm travması ve asırlar önceki o kaotik savaş paniği, bölgede hala aktif bir astral yıkım enerjisi yayar.",5"Noratus Kadim Mezarlığı","Geğarkunik","Ermenistan","Binlerce asırlık 'Haçkar' (haç taşı) anıtının bulunduğu, ordu gibi dizilmiş devasa bir Orta Çağ mezarlığı. Efsaneye göre işgalcileri korkutmak için ölülerin ruhlarıyla canlandırılan bu taşların arasında gece dolaşırken, o devasa atalardan kalma keder ve izlendiğinizi hissettiren binlerce görünmez göz auranızı sarsar.",4"Amberd Kalesi (Bulutların Kalesi)","Aragatsotn","Ermenistan","Aragats Dağı'nın acımasız kışlarına ve Moğol ordularının vahşi katliamlarına sahne olmuş, sarp uçurumların kenarındaki bu harabe. Gece rüzgarının taşıdığı o dondurucu savaş nidası ve kılıçtan geçirilen askerlerin kanlı, paslı ölüm frekansı; kalenin yıkık surlarını devasa bir ruhsal savaş alanına çevirir.",4"Garni Vadisi ve Tapınağı","Kotayk","Ermenistan","Hristiyanlık öncesi pagan tanrılarına kanlı adakların sunulduğu, bazalt sütunlardan oluşan o devasa ve ürkütücü vadi. Gece çöktüğünde tapınağın etrafında uyanan o ilkel (primal) maji enerjisi ve eski rahiplerin ritmik ilahileri, ziyaretçilerin zihinsel kalkanlarını yıkarak onları derin bir şamanik transa zorlar.",5"Azhdahak Dağı (Ejderha Zirvesi)","Geğam Dağları","Ermenistan","Adını Pers mitolojisindeki şeytani yılan kraldan (Zahhak) alan bu volkanik dağ ve krater gölü. Yeraltı dünyasının ve su elementallerinin (Vishaplar) hüküm sürdüğü bu izole zirvede, aklınızı zorlayan devasa manyetik anomaliler ve sizi o karanlık krater gölüne atlamaya çağıran hipnotik, yutucu bir enerji mevcuttur.",4"Spitak Fay Hattı (1988 Yıkımı)","Lori","Ermenistan","On binlerce insanın saniyeler içinde enkaz altında kalarak can verdiği devasa depremin merkez üssü. Toplu mezarların ve terk edilmiş yıkıntıların arasında durduğunuzda, havada asılı kalan o devasa keder, panik ve aniden kopan hayatların yarattığı boğucu yas frekansı, empatları anında gözyaşlarına boğar.",5"Bjni Kalesi Zindanları","Kotayk","Ermenistan","Timur'un ordularının acımasız kuşatmasında kan gölüne dönen ve halkın sığındığı gizli yeraltı tünellerinin çöktüğü bu Orta Çağ kalesi. Karanlık dehlizlerde havasızlıktan ve korkudan can veren sivillerin o çaresiz feryatları, taşların arasına mühürlenmiş aktif bir poltergeist enerjisi olarak hala yankılanmaktadır.",4"Lori Berd Harabeleri","Lori","Ermenistan","Derin kanyonlarla çevrili, Orta Çağ'da tamamen terk edilip ormanın ve vahşi doğanın merhametine bırakılan bu hayalet şehir. Yıkık kiliselerin ve boş sokakların arasında rüzgarın uğultusu, veba ve savaştan kaçanların ağıtlarını taklit eder; buradaki mutlak sessizlik, insanın kendi zihniyle girdiği korkunç bir savaşa dönüşür.",3"Zvartnots Harabeleri","Armavir","Ermenistan","Kadim bir depremle yerle bir olan ve dairesel mimarisiyle gizemli okült enerjiler barındıran bu devasa katedralin yıkıntıları. Gece ay ışığı bu kusursuz geometrik harabelere vurduğunda, binanın geçmişteki o kutsal aurasıyla depremin yarattığı o yıkıcı kaos enerjisi birbirine girerek insanı sersemleten astral bir girdap yaratır.",4"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Ermenistan kayitlari eklendi.")
